from __future__ import annotations

from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse

from .esp_niche import require_esp_social_member

router = APIRouter()


@router.get("/command-center/social/publish-queue", response_class=HTMLResponse, include_in_schema=False)
def publish_queue_portal(request: Request):
    _member, esp_membership, profile = require_esp_social_member(request)
    definition = profile["catalog"]
    accent = escape(definition["theme"]["accent"])
    secondary = escape(definition["theme"]["secondary"])
    niche = escape(definition["title"])
    role = esp_membership.get("roles") or ("owner" if esp_membership.get("status") == "owner" else "member")

    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><meta name='robots' content='noindex,nofollow'><meta name='theme-color' content='#05040b'><title>ESP Social Publish Queue</title><style>
:root{--accent:__ACCENT__;--secondary:__SECONDARY__;--bg:#03040a;--panel:#0d0f1b;--line:#ffffff1c;--text:#fff;--muted:#b7bbce;--green:#79e3a8;--amber:#ffd36b;--red:#ff8f9d;--cyan:#5ce8ff}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:radial-gradient(circle at 8% 0,var(--secondary),transparent 28%),radial-gradient(circle at 92% 4%,var(--accent),transparent 23%),linear-gradient(#03040a,#070811 65%,#020309)}a{color:inherit;text-decoration:none}button,select{font:inherit}.wrap{width:min(1320px,calc(100% - 28px));margin:auto}.nav{position:sticky;top:0;z-index:10;background:#05060bee;backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.navin{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:14px}.brand{font-weight:950}.brand small{display:block;color:var(--accent);font-size:.64rem;text-transform:uppercase;letter-spacing:.08em}.actions{display:flex;gap:7px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#ffffff08;color:#fff;border-radius:12px;padding:9px 12px;font-weight:850;cursor:pointer}.btn.primary{border:0;background:linear-gradient(115deg,var(--accent),var(--secondary));color:#130b18}.btn:disabled{opacity:.5;cursor:not-allowed}.hero{padding:42px 0 20px}.eyebrow{color:var(--accent);font-size:.72rem;font-weight:950;letter-spacing:.17em;text-transform:uppercase}.hero h1{font-size:clamp(2.5rem,6vw,4.8rem);letter-spacing:-.05em;line-height:.95;margin:.14em 0 .2em}.hero h1 span{background:linear-gradient(95deg,#fff,var(--accent),var(--secondary));background-clip:text;color:transparent}.lead{color:var(--muted);max-width:960px;line-height:1.6}.toolbar,.panel{border:1px solid var(--line);background:linear-gradient(145deg,#101323e8,#080a14f0);border-radius:20px;padding:14px}.toolbar{display:grid;grid-template-columns:1fr auto auto;gap:9px;align-items:center;margin-bottom:12px}.field{width:100%;border:1px solid var(--line);background:#070913;color:#fff;border-radius:11px;padding:10px}.grid{display:grid;grid-template-columns:repeat(6,1fr);gap:9px;margin-bottom:12px}.metric{border:1px solid var(--line);background:#ffffff05;border-radius:15px;padding:13px}.metric b{display:block;font-size:1.5rem}.metric small,.muted{color:var(--muted)}.truth{border:1px solid #5ce8ff42;background:#5ce8ff0b;border-radius:16px;padding:13px;margin-bottom:12px;color:#dffaff}.entry{display:grid;grid-template-columns:1.4fr .65fr .85fr .65fr 1.5fr auto;gap:10px;align-items:center;border:1px solid var(--line);background:#ffffff05;border-radius:15px;padding:13px;margin:9px 0}.entry strong{display:block}.small{font-size:.73rem}.state{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:5px 8px;font-size:.7rem;font-weight:900;text-transform:uppercase;letter-spacing:.04em}.state.queued,.state.published{color:var(--green);border-color:#79e3a850}.state.planned{color:var(--cyan);border-color:#5ce8ff50}.state.blocked,.state.failed{color:var(--red);border-color:#ff8f9d55}.state.publishing{color:var(--amber);border-color:#ffd36b55}.reason{color:#ffd7dc;font-size:.72rem;line-height:1.4}.empty{border:1px dashed #ffffff2a;border-radius:16px;padding:26px;text-align:center;color:var(--muted)}.notice{display:none;border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin-bottom:12px}.notice.show{display:block}.notice.error{color:#ffd6dc;border-color:#ff8f9d50}.footer{border-top:1px solid var(--line);padding:28px 0 40px;margin-top:32px;color:var(--muted);font-size:.84rem}@media(max-width:1050px){.grid{grid-template-columns:repeat(3,1fr)}.entry{grid-template-columns:1fr 1fr}.entry .wide{grid-column:1/-1}}@media(max-width:650px){.toolbar{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,1fr)}.entry{grid-template-columns:1fr}.entry .wide{grid-column:auto}.actions .optional{display:none}}
</style></head><body><nav class='nav'><div class='wrap navin'><a class='brand' href='/command-center'>Elevate Souls Productions<small>Private Creator & Agent Hub · Production Queue</small></a><div class='actions'><a class='btn primary' href='/command-center/social'>Social Management</a><a class='btn optional' href='/command-center/social/approvals'>Approvals</a><a class='btn optional' href='/command-center/social-insights'>Insights</a></div></div></nav><main class='wrap'><section class='hero'><div class='eyebrow'>__NICHE__ · __ROLE__ · Provider-aware scheduling</div><h1>Social <span>Publish Queue</span></h1><p class='lead'>See exactly what is planned, blocked, due or ready for an authorised official platform adapter. This screen does not pretend queued content has been published: provider confirmation and an external post ID are required before a variant can become published.</p></section><div id='notice' class='notice'></div><section class='toolbar'><select id='space' class='field' aria-label='Social House'></select><button class='btn' onclick='loadQueue()'>Reload</button><button class='btn primary' onclick='refreshQueue()'>Revalidate Queue</button></section><section class='grid' id='metrics'></section><section class='truth' id='truth'>Loading queue state…</section><section class='panel'><div id='entries' class='empty'>Choose a Social House to inspect its production queue.</div></section></main><footer class='footer'><div class='wrap'><strong>Elevate Souls Productions</strong> · Private ESP Creator & Agent Social Management · Powered by Aura AI Systems</div></footer><script>
const BASE='/command-center/api/social';const q=id=>document.getElementById(id);let snapshot=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notice(m,bad=false){const n=q('notice');n.textContent=m;n.className='notice show'+(bad?' error':'');clearTimeout(window._nt);window._nt=setTimeout(()=>n.className='notice',6000)}
async function api(path,opt={}){const r=await fetch(BASE+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch(_){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}
function pretty(v){return String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}
async function loadSpaces(){try{const d=await api('/spaces');const spaces=d.spaces||[];q('space').innerHTML=spaces.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');if(spaces.length){q('space').onchange=loadQueue;await loadQueue()}else{q('metrics').innerHTML='';q('truth').textContent='Create a Social House in Social Management first.';q('entries').className='empty';q('entries').textContent='No Social Houses yet.'}}catch(e){notice(e.message,true)}}
function metric(label,value){return `<div class="metric"><b>${Number(value||0)}</b><small>${esc(label)}</small></div>`}
function render(d){snapshot=d;q('truth').textContent=d.truthful_state||'Queued does not mean published.';const c=d.counts||{};q('metrics').innerHTML=metric('Queued',c.queued)+metric('Planned',c.planned)+metric('Blocked',c.blocked)+metric('Publishing',c.publishing)+metric('Published',c.published)+metric('Failed',c.failed);const rows=d.entries||[];if(!rows.length){q('entries').className='empty';q('entries').textContent='No scheduled or auto-publish variants are in this queue yet.';return}q('entries').className='';q('entries').innerHTML=rows.map(x=>{const reasons=(x.reasons||[]).map(r=>esc(r)).join(' · ');const retry=['blocked','failed'].includes(x.state)?`<button class="btn" onclick="retryEntry('${esc(x.id)}')">Retry</button>`:'';return `<div class="entry"><div><strong>${esc(x.content_title)}</strong><span class="muted small">${esc(pretty(x.content_type))}</span></div><div><b>${esc(pretty(x.platform))}</b><div class="muted small">${x.due?'Due now':'Not due'}</div></div><div><span class="state ${esc(x.state)}">${esc(pretty(x.state))}</span></div><div><div class="small">${x.retry_requests||0} retries</div><div class="muted small">${esc(x.adapter||'No adapter')}</div></div><div class="wide"><div class="small">${esc(x.scheduled_at||'No schedule')}</div>${reasons?`<div class="reason">${reasons}</div>`:'<div class="muted small">All current queue gates satisfied.</div>'}</div><div>${retry}</div></div>`}).join('')}
async function loadQueue(){const id=q('space').value;if(!id)return;try{render(await api(`/spaces/${encodeURIComponent(id)}/publish-queue`))}catch(e){notice(e.message,true)}}
async function refreshQueue(){const id=q('space').value;if(!id)return;try{render(await api(`/spaces/${encodeURIComponent(id)}/publish-queue/refresh`,{method:'POST'}));notice('Queue revalidated against schedule, approval, connection and adapter gates.')}catch(e){notice(e.message,true)}}
async function retryEntry(id){const space=q('space').value;if(!space)return;try{await api(`/spaces/${encodeURIComponent(space)}/publish-queue/${encodeURIComponent(id)}/retry`,{method:'POST'});await loadQueue();notice('Retry request recorded and queue state recalculated.')}catch(e){notice(e.message,true)}}
loadSpaces();
</script></body></html>"""
    return HTMLResponse(
        html.replace("__ACCENT__", accent)
        .replace("__SECONDARY__", secondary)
        .replace("__NICHE__", niche)
        .replace("__ROLE__", escape(str(role).title()))
    )


__all__ = ["router"]
